/// <reference lib="dom" />
/// <reference lib="dom.iterable" />

import {
  AbsoluteFill,
  Easing,
  getRemotionEnvironment,
  Img,
  Interactive,
  type InteractivitySchema,
  interpolate,
  Sequence,
  staticFile,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import {
  type ComponentProps,
  createContext,
  type CSSProperties,
  forwardRef,
  type ReactNode,
  useContext,
} from "react";
import { loadFont as loadGeist } from "@remotion/google-fonts/Geist";
import { loadFont as loadInstrumentSerif } from "@remotion/google-fonts/InstrumentSerif";
import { loadFont as loadInter } from "@remotion/google-fonts/Inter";
import { loadFont as loadMontserrat } from "@remotion/google-fonts/Montserrat";
import { loadFont as loadOutfit } from "@remotion/google-fonts/Outfit";
import { loadFont as loadSpaceGrotesk } from "@remotion/google-fonts/SpaceGrotesk";

/**
 * The type faces a scene's `fontFamily` may name.
 *
 * ## Why an allowlist and not a free string
 *
 * Every component in this registry loads its face through
 * `@remotion/google-fonts` rather than a CSS variable, for the reason spelled
 * out at the top of each one: a Remotion bundle has none of the app's CSS, so
 * `var(--font-…)` gets you the right face in the Player and a **fallback in the
 * mp4**. A bare family name handed to a component has exactly the same problem
 * — the browser preview finds it, the render does not, and the bug is invisible
 * until someone plays the file.
 *
 * So a name only counts as a font here if this module has loaded it. Values map
 * label → the real CSS family string `loadFont` returns, which is not always the
 * label ("Instrument Serif", not "InstrumentSerif").
 *
 * ## A raw stack still works
 *
 * `resolveFont` passes anything it does not recognise straight through, so a
 * caller who has loaded their own face — a brand font, a local `@font-face` —
 * names it directly and gets it. The allowlist is the safe path, not the only one.
 *
 * ponytail: all six load at module scope, so a render fetches six latin subsets
 * whether or not the video uses them. Move to a lazy per-family `loadFont()` if
 * bundle time ever shows up in a render trace.
 */
const FONTS: Record<string, string> = {
  Inter: loadInter("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Geist: loadGeist("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  "Space Grotesk": loadSpaceGrotesk("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Outfit: loadOutfit("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Montserrat: loadMontserrat("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  // 400 is the only weight this family ships. Asking for 600 throws.
  "Instrument Serif": loadInstrumentSerif("normal", {
    weights: ["400"],
    subsets: ["latin"],
  }).fontFamily,
};

/**
 * What a select control offers. `DEFAULT_FONT` first: a scene's own face is a
 * design decision, so the knob has to have an "off", and it has to be the
 * value it ships at.
 */
const DEFAULT_FONT = "Default";

/**
 * Label → loaded CSS family. Anything unrecognised passes through unchanged, so
 * a caller's own stack is never swallowed. `undefined` in, `undefined` out —
 * that is the signal for "keep the component's own face".
 */
const resolveFont = (name?: string): string | undefined =>
  !name || name === DEFAULT_FONT ? undefined : (FONTS[name] ?? name);

interface KitTheme {
  background: string;
  foreground: string;
  card: string;
  cardForeground: string;
  popover: string;
  popoverForeground: string;
  primary: string;
  primaryForeground: string;
  secondary: string;
  secondaryForeground: string;
  muted: string;
  mutedForeground: string;
  accent: string;
  accentForeground: string;
  destructive: string;
  destructiveForeground: string;
  border: string;
  input: string;
  ring: string;
  radius: number;
  /**
   * The face every text component paints with, as a label from `fonts.ts` or a
   * CSS family the caller has loaded themselves.
   *
   * Optional and defaulted to nothing on purpose: unset, each component keeps
   * the face it was designed around, so adding this token changed no existing
   * render. Set it on `KitUIProvider` and one value re-skins a whole
   * timeline — which is the only reason it lives on the theme rather than
   * staying a per-component prop.
   */
  fontFamily?: string;
}

/**
 * The shadcn token set, as concrete values.
 *
 * ## These are a mirror of `app/globals.css`, and that is the whole point
 *
 * A component we ship lands next to somebody's `Button` and `Input`, and those
 * paint from the CSS custom properties in `globals.css`. A scene that paints
 * from a *different* set of greys is a scene that clashes with the app it was
 * installed into — which is exactly what happened here: this file was written
 * first, `globals.css` was later re-skinned warm, and for a while the site and
 * the videos it sells were two different products.
 *
 * So every value below is the **literal string** from the corresponding
 * `--token` in `app/globals.css` (`:root` for light, `.dark` for dark). Hex, not
 * oklch, purely so that drift is a string comparison — if the two files ever
 * disagree again, `pnpm run check:tokens` says so and prints the pairs.
 *
 * ## Why not just read `var(--token)`?
 *
 * Because a Remotion bundle has none of the app's CSS, so `var()` resolves to
 * nothing under the headless renderer and cannot be interpolated by `mixOklch`
 * at all (see the guard in `color.ts`). Concrete values are not a shortcut here,
 * they are the only thing that survives a render. Users on a different palette
 * override via `KitUIProvider` or a component's `theme` prop.
 *
 * ## `radius` is the one value that flows the other way
 *
 * `globals.css` sets `--radius: 0.28rem` *so that* its `--radius-3xl` step lands
 * on this 10 — see the note beside it there. It is not drift; do not "fix" it.
 */
const defaultLightTheme: KitTheme = {
  background: "#faf9f6", // page — warm off-white
  foreground: "#141414", // text
  card: "#ffffff", // surface on the page
  cardForeground: "#141414",
  popover: "#ffffff",
  popoverForeground: "#141414",
  primary: "#3072db", // accent blue
  primaryForeground: "#ffffff",
  secondary: "#f2f0eb", // subtle fill
  secondaryForeground: "#141414",
  muted: "#f2f0eb",
  mutedForeground: "#6e6a63", // secondary text, leading icons
  accent: "#f2f0eb", // hover wash
  accentForeground: "#141414",
  destructive: "#d92d20",
  // `globals.css` defines no --destructive-foreground; white is the only thing
  // that reads on #d92d20, and shadcn's own default agrees.
  destructiveForeground: "#ffffff",
  border: "#d9d9d9", // hairline
  input: "#d9d9d9",
  ring: "#3072db",
  radius: 10,
};

const defaultDarkTheme: KitTheme = {
  background: "#0a0a0b", // page — near-black
  foreground: "#fafafa", // text
  card: "#141417", // surface, a shade above the page
  cardForeground: "#fafafa",
  popover: "#141417",
  popoverForeground: "#fafafa",
  primary: "#3072db", // the same accent blue in both modes
  primaryForeground: "#ffffff",
  secondary: "#1d1d21", // subtle fill
  secondaryForeground: "#fafafa",
  muted: "#1b1b1f",
  mutedForeground: "#a1a1aa", // secondary text, leading icons
  accent: "#1d1d21", // hover wash
  accentForeground: "#fafafa",
  destructive: "#f97066",
  destructiveForeground: "#fafafa",
  border: "#26272b", // hairline — separation is borders, not shadows
  input: "#26272b",
  ring: "#3072db",
  radius: 10,
};

interface KitThemeContextValue {
  theme?: Partial<KitTheme>;
  mode?: "light" | "dark";
}

const KitThemeContext = createContext<KitThemeContextValue>({});

function useKitTheme(
  override?: Partial<KitTheme>,
  modeOverride?: "light" | "dark",
): KitTheme {
  const ctx = useContext(KitThemeContext);
  const mode = modeOverride ?? ctx.mode ?? "light";
  const base = mode === "dark" ? defaultDarkTheme : defaultLightTheme;
  return { ...base, ...ctx.theme, ...override };
}

/**
 * A Marvel-Studios-style flicker reveal: images flip full-screen at a constant
 * fast rate right to the end, then cross-fade — the flicker fading OUT while the
 * logo and brand name fade IN, together, in one move.
 */

export interface LogoFlickerProps {
  /** The logo mark (simple/monochrome — it resolves over the dark backdrop). */
  logoSrc?: string;
  /** Brand name shown under the logo. */
  brandName?: string;
  /** Image pool the flicker flips through, full-screen. */
  images?: string[];
  /** Frames each image holds — the (constant) flip speed. */
  flipInterval?: number;
  /** Backdrop color. Overrides the design system's `background`. */
  background?: string;
  speed?: number;
  className?: string;
  /** Design-system token overrides. */
  theme?: Partial<KitTheme>;
  /**
   * Defaults to `"dark"`: the shipped `logoSrc` is a white mark, so the stage
   * has to be dark for it to read. Pass `"light"` with a dark logo asset.
   */
  mode?: "light" | "dark";
  /**
   * The face this scene paints its words in — a label from `fonts.ts`
   * ("Inter", "Space Grotesk", "Instrument Serif") or a CSS family you have
   * loaded yourself. Unset, the scene keeps the face it was designed around.
   *
   * Overrides `theme.fontFamily`, which is how a brand kit re-skins a whole
   * timeline from one value.
   */
  fontFamily?: string;
}

const FONT_FAMILY =
  'Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif';

/** No pictures: the Element passes its own. */
const DEFAULT_IMAGES: string[] = [];

// ─── Timeline (frames @ 30fps; ~3.5s) ──────────────────────────────────────────
/** Default frames per image — the flip speed, held constant to the very end. */
const FLIP_INTERVAL = 2;
/**
 * The single cross-fade window: the flicker fades OUT and the logo + name fade
 * IN across exactly these frames — simultaneously, not one after the other.
 */
const FADE_START = 66;
const FADE_END = 84;

const EASE = Easing.bezier(0.2, 0.6, 0.35, 1);
const CLAMP = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

/**
 * Which image shows at `frame`. A constant `interval` (no deceleration) and a
 * coprime stride so it hops through the whole pool as it flips.
 */
function flickerImage(
  frame: number,
  count: number,
  interval: number = FLIP_INTERVAL,
): number {
  const n = Math.max(1, count);
  const step = Math.floor(frame / Math.max(1, interval));
  return (step * 7) % n;
}

/** Flicker opacity — solid, then fades out across the cross-fade window. */
function flickerOpacity(frame: number): number {
  return interpolate(frame, [FADE_START, FADE_END], [1, 0], CLAMP);
}

/** Logo + name opacity — the INVERSE of the flicker, on the SAME window. */
function revealOpacity(frame: number): number {
  return interpolate(frame, [FADE_START, FADE_END], [0, 1], CLAMP);
}

/** A small settle on the lockup as it fades in (shared by logo and name). */
function revealScale(frame: number): number {
  return interpolate(frame, [FADE_START, FADE_END], [0.92, 1], {
    ...CLAMP,
    easing: EASE,
  });
}

/** Rewrite root-relative assets through staticFile everywhere but the Player. */
function resolveSrc(src: string): string {
  const isLocal = src.startsWith("/") && !src.startsWith("//");
  if (!isLocal || getRemotionEnvironment().isPlayer) return src;
  // A value that already came out of staticFile() carries the static base
  // (`/static-<hash>/…`); running it through again would prefix it twice.
  const base = staticFile("_").slice(0, -2);
  if (base && src.startsWith(`${base}/`)) return src;
  try {
    return staticFile(src.replace(/^\/+/, ""));
  } catch {
    return src;
  }
}

function LogoFlickerScene({
  logoSrc = staticFile("logo-flicker/logo.png"),
  brandName = "Acme",
  images = DEFAULT_IMAGES,
  flipInterval = 2,
  background,
  speed = 1,
  className,
  theme,
  mode,
  fontFamily,
}: LogoFlickerProps) {
  const frame = useCurrentFrame() * speed;
  const { width, height } = useVideoConfig();
  const t = useKitTheme(theme, mode ?? "dark");
  const face = resolveFont(fontFamily ?? t.fontFamily) ?? FONT_FAMILY;
  const stage = background ?? t.background;
  const short = Math.min(width, height);
  const isRendering = getRemotionEnvironment().isRendering;

  const flkOpacity = flickerOpacity(frame);
  const reveal = revealOpacity(frame);
  const scale = revealScale(frame);
  const imgIdx = flickerImage(frame, images.length, flipInterval);

  const logoSize = Math.round(short * 0.15);
  const nameSize = Math.round(short * 0.055);

  return (
    <div
      className={className}
      style={{
        position: "absolute",
        inset: 0,
        overflow: "hidden",
        backgroundColor: stage,
        fontFamily: face,
        textRendering: "geometricPrecision",
      }}
    >
      {/* Full-screen flicker */}
      {flkOpacity > 0 && (
        <Img
          showInTimeline={false}
          src={resolveSrc(images[imgIdx] ?? images[0])}
          style={{
            position: "absolute",
            inset: 0,
            width: "100%",
            height: "100%",
            maxWidth: "none",
            objectFit: "cover",
            opacity: flkOpacity,
            ...(isRendering ? {} : { willChange: "opacity" as const }),
          }}
        />
      )}

      {/* Logo + brand name — fade IN on the same window the flicker fades OUT */}
      {reveal > 0 && (
        <div
          style={{
            position: "absolute",
            inset: 0,
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            justifyContent: "center",
            gap: Math.round(short * 0.02),
            opacity: reveal,
            transform: `scale(${scale})`,
            transformOrigin: "center center",
          }}
        >
          <Img
            showInTimeline={false}
            src={resolveSrc(logoSrc)}
            style={{
              width: logoSize,
              height: logoSize,
              maxWidth: "none",
              objectFit: "contain",
            }}
          />
          <div
            style={{
              color: t.foreground,
              fontSize: nameSize,
              fontWeight: 600,
              letterSpacing: "-0.02em",
            }}
          >
            {brandName}
          </div>
        </div>
      )}
    </div>
  );
}

/* ─────────────────────────────────────────────────────────────────────────
   Remotion Studio
   ───────────────────────────────────────────────────────────────────────── */

type LogoFlickerElementProps = Omit<
  ComponentProps<typeof LogoFlickerScene>,
  | "from"
  | "durationInFrames"
  | "trimBefore"
  | "playbackRate"
  | "loop"
  | "freeze"
  | "hidden"
  | "name"
  | "showInTimeline"
  | "cropLeft"
  | "cropRight"
  | "cropTop"
  | "cropBottom"
  | "premountFor"
  | "postmountFor"
  | "styleWhilePremounted"
  | "styleWhilePostmounted"
  | "controls"
  | "images"
> & {
  readonly image1?: string;
  readonly image2?: string;
  readonly image3?: string;
  readonly image4?: string;
  readonly image5?: string;
  readonly image6?: string;
  readonly image7?: string;
  readonly image8?: string;
  readonly style?: CSSProperties;
};

/** What a prop falls back to when Studio does not pass it, reset included. */
const LogoFlickerDefaults = {
  brandName: "Acme",
  logoSrc: staticFile("logo-flicker/logo.png"),
  flipInterval: 2,
  background: "transparent",
  speed: 1,
  mode: "light",
  image1: staticFile("logo-flicker/photo-1.webp"),
  image2: staticFile("logo-flicker/photo-2.webp"),
  image3: staticFile("logo-flicker/photo-3.jpg"),
  image4: staticFile("logo-flicker/photo-4.jpg"),
  image5: staticFile("logo-flicker/photo-5.jpg"),
  image6: staticFile("logo-flicker/photo-6.jpg"),
  image7: staticFile("logo-flicker/photo-7.jpg"),
  image8: staticFile("logo-flicker/photo-8.jpg"),
} satisfies Partial<LogoFlickerElementProps>;

/** The Inspector's controls. Timing, transform, crop and premount come with `wrapInSequence`. */
const LogoFlickerSchema = {
  brandName: {
    type: "text-content",
    default: "Acme",
    description: "Brand name",
  },
  logoSrc: {
    type: "asset",
    assetType: "image",
    default: staticFile("logo-flicker/logo.png"),
    description: "Logo (simple, monochrome)",
  },
  fontFamily: { type: "font-family", default: undefined, description: "Font" },
  speed: {
    type: "number",
    default: 1,
    min: 1,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
    keyframable: false,
  },
  image1: {
    type: "asset",
    assetType: "image",
    default: staticFile("logo-flicker/photo-1.webp"),
    description: "Image 1",
  },
  image2: {
    type: "asset",
    assetType: "image",
    default: staticFile("logo-flicker/photo-2.webp"),
    description: "Image 2",
  },
  image3: {
    type: "asset",
    assetType: "image",
    default: staticFile("logo-flicker/photo-3.jpg"),
    description: "Image 3",
  },
  image4: {
    type: "asset",
    assetType: "image",
    default: staticFile("logo-flicker/photo-4.jpg"),
    description: "Image 4",
  },
  image5: {
    type: "asset",
    assetType: "image",
    default: staticFile("logo-flicker/photo-5.jpg"),
    description: "Image 5",
  },
  image6: {
    type: "asset",
    assetType: "image",
    default: staticFile("logo-flicker/photo-6.jpg"),
    description: "Image 6",
  },
  image7: {
    type: "asset",
    assetType: "image",
    default: staticFile("logo-flicker/photo-7.jpg"),
    description: "Image 7",
  },
  image8: {
    type: "asset",
    assetType: "image",
    default: staticFile("logo-flicker/photo-8.jpg"),
    description: "Image 8",
  },
} as const satisfies InteractivitySchema;

/**
 * In over the first frames, out over the last. Opacity only: nothing moves, so
 * no glyph can snap to the pixel grid on the way out.
 */
function LogoFlickerFade({ children }: { children: ReactNode }) {
  const frame = useCurrentFrame();
  const enter = Math.min(1, (frame + 1) / 6);
  const { durationInFrames } = useVideoConfig();
  const left = Math.min(1, Math.max(0, (durationInFrames - 1 - frame) / 12));
  const leave = left * left;
  return (
    <AbsoluteFill showInTimeline={false} style={{ opacity: enter * leave }}>
      {children}
    </AbsoluteFill>
  );
}

const LogoFlickerInner = forwardRef<HTMLDivElement, LogoFlickerElementProps>(
  ({ style, ...props }, ref) => {
    // The layer's length, from the Sequence `wrapInSequence` puts around this.
    const { durationInFrames } = useVideoConfig();
    const {
      image1,
      image2,
      image3,
      image4,
      image5,
      image6,
      image7,
      image8,
      ...rest
    } = { ...LogoFlickerDefaults, ...props };
    // The scene measures its copy once, on mount. An Inspector edit changes the
    // props without remounting it, so the key does.
    const key = JSON.stringify(props, (k, v) =>
      k === "children" ? undefined : v,
    );

    // width/height are what useVideoConfig() reports inside this Sequence, so
    // the scene lays itself out in its stage rather than the whole composition.
    // It is not a layer of its own: the one Studio shows is the wrapper's.
    return (
      <Sequence
        layout="none"
        showInTimeline={false}
        durationInFrames={durationInFrames}
        width={1280}
        height={720}
      >
        <div
          ref={ref}
          style={{
            position: "relative",
            width: 1280,
            height: 720,
            overflow: "hidden",
            color: "black",
            fontFamily: "initial",
            fontSize: 16,
            fontStyle: "normal",
            fontVariant: "normal",
            fontWeight: 400,
            fontStretch: "normal",
            fontKerning: "auto",
            fontFeatureSettings: "normal",
            fontVariationSettings: "normal",
            lineHeight: "normal",
            letterSpacing: "normal",
            wordSpacing: "normal",
            textAlign: "start",
            textIndent: 0,
            textTransform: "none",
            textShadow: "none",
            textRendering: "auto",
            whiteSpace: "normal",
            wordBreak: "normal",
            overflowWrap: "normal",
            hyphens: "manual",
            direction: "ltr",
            visibility: "visible",
            ...style,
          }}
        >
          <LogoFlickerFade>
            <LogoFlickerScene
              key={key}
              {...rest}
              images={[
                image1,
                image2,
                image3,
                image4,
                image5,
                image6,
                image7,
                image8,
              ].filter((s): s is string => Boolean(s))}
            />
          </LogoFlickerFade>
        </div>
      </Sequence>
    );
  },
);

export const LogoFlicker = Interactive.withSchema({
  Component: LogoFlickerInner,
  componentName: "<LogoFlicker>",
  schema: LogoFlickerSchema,
  wrapInSequence: true,
});
